sp_widget.css:
.recent-requests {
  background-color: white;
  padding: 20px;
  border-radius: 10px;
  box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
  margin-bottom: 20px;
}

.recent-requests h2 {
  color: #004080;
  margin-bottom: 15px;
}

.recent-requests table {
  width: 100%;
  border-collapse: collapse;
}

.recent-requests th, .recent-requests td {
  border: 1px solid #ddd;
  padding: 10px;
  text-align: center;
}

.recent-requests th {
  background-color: #004080;
  color: white;
}

.recent-requests td a {
  color: #004080;
  text-decoration: none;
  font-weight: bold;
}

.recent-requests td a:hover {
  color: #ffcc00;
}

sp_widget.script:
(function() {
    var userSysId = gs.getUserID();
    var tableName = 'Employee Onboarding'; // Replace with your actual table name

    var gr = new GlideRecord(tableName);

    if (!gr.isValid()) {  
        gs.error("Table '" + tableName + "' does not exist or is invalid.");
        data.requests = [];
        return;
    }

    if (!gr.isValidField('requested_for')) {  
        gs.error("Field 'requested_for' not found in the table '" + tableName + "'.");
        data.requests = [];
        return;
    }

    gr.addQuery('requested_for', userSysId);
    gr.orderByDesc('sys_created_on');
    gr.setLimit(5);
    gr.query();

    var requests = [];
    while (gr.next()) {
        requests.push({
            sys_id: gr.getValue('sys_id') || 'N/A',
            number: gr.getValue('number') || 'N/A',
            type: gr.getDisplayValue('request_type') || 'N/A', // Ensure request_type exists
            status: gr.getDisplayValue('state') || 'N/A',
            created_on: gr.getDisplayValue('sys_created_on') || 'N/A'
        });
    }

    data.requests = requests;
})();
